"""Glossary lookup for Thorium-Based Nuclear Energy Systems."""

GLOSSARY = {
    "capacity factor": "actual output divided by the maximum possible output over a period",
    "levelized cost": "the average cost per unit of energy over the system lifetime",
    "dispatchable": "able to produce power on demand rather than when nature allows",
    "round-trip efficiency": "energy recovered from storage divided by energy put in",
    "baseload": "the minimum demand a grid must serve around the clock",
    "microgrid": "a local energy network that can operate connected to or apart from the main grid",
}

def lookup(term):
    key = term.strip().lower()
    for k, v in GLOSSARY.items():
        if k.lower() == key:
            return k + ": " + v
    cands = [k for k in GLOSSARY if key in k.lower()]
    return ("Did you mean: " + ", ".join(cands)) if cands else "No entry."


if __name__ == "__main__":
    print("Thorium-Based Nuclear Energy Systems glossary — %d terms" % len(GLOSSARY))
    for t in list(GLOSSARY)[:3]:
        print("-", lookup(t))

"""Piece model: Primary Conversion Unit — part of the Thorium-Based Nuclear Energy Systems system."""
import random

class ThoriumBasedNuclearEnergySystemsPiece1PrimaryConversionU:
    """Models the Primary Conversion Unit piece: specification check and behavior sample."""

    SPEC = {"piece": "Primary Conversion Unit", "interfaces": 3, "redundancy": 2}

    def __init__(self, seed=11):
        self.rng = random.Random(seed)

    def spec_check(self):
        """Verify the piece meets its interface contract."""
        results = {}
        for i in range(self.SPEC["interfaces"]):
            # simulated conformance measurement around a nominal value
            measured = 1.0 + self.rng.uniform(-0.04, 0.04)
            results["interface_%d" % i] = round(measured, 3)
        ok = all(0.94 <= v <= 1.06 for v in results.values())
        return {"pass": ok, "measurements": results}

    def simulate(self, cycles=24):
        """Sample operating behavior over a number of cycles."""
        health = 1.0
        for _ in range(cycles):
            stress = self.rng.uniform(0.0, 0.06)
            health = max(0.0, health - stress * 0.2)
            health = min(1.0, health + 0.05)  # recovery / maintenance
        return {"cycles": cycles, "health": round(health, 3),
                "redundancy_ok": health > 0.5}


if __name__ == "__main__":
    m = ThoriumBasedNuclearEnergySystemsPiece1PrimaryConversionU(seed=11)
    sc = m.spec_check()
    sm = m.simulate(24)
    print("Primary Conversion Unit — Thorium-Based Nuclear Energy Systems")
    print("spec check pass:", sc["pass"], "| measurements:", sc["measurements"])
    print("health after", sm["cycles"], "cycles:", sm["health"])

